Per zod@4.5.4:

Yes. In zod v4 classic, `z.email()` is a standalone constructor declared as `export declare function email(params?: string | core.$ZodEmailParams): ZodEmail;` returning a `ZodEmail` (which extends `ZodStringFormat<"email">`). The usage for validating an email address string is `z.email()` (optionally passing a string error message or params). The provided content does not include any mention of `z.string().email()` or a deprecation notice for it, so that part cannot be confirmed from this package.

Source excerpt:
> // v4/classic/schemas.d.ts
> export interface ZodEmail extends ZodStringFormat<"email"> {
>     _zod: core.$ZodEmailInternals;
> }
> export declare const ZodEmail: core.$constructor<ZodEmail>;
> export declare function email(params?: string | core.$ZodEmailParams): ZodEmail;

Per docs-live-ts (project source):

config.ts exports two names: `configSchema`, a `z.strictObject` with fields `name: z.string()`, `port: z.number().int().min(1).max(65535)`, and `adminEmail: z.email()`; and `loadConfig(path: string = 'config.json')`, which returns the union `{ ok: true, data: result.data }` (parsed config object) or `{ ok: false, issues: [...] }` (either custom issues for read/parse failures or `result.error.issues` from the schema). The function has no explicit return-type annotation, so it's inferred.

Source excerpt:
> export function loadConfig(path: string = 'config.json') {
>   let raw: string;
>   try {
>     raw = readFileSync(path, "utf8");
>   } catch (err) {
>     const message = err instanceof Error ? err.message : String(err);
>     return { ok: false, issues: [{ code: "custom", message, path: [] }] };
>   }
> 
>   let parsed: unknown;
>   try {
>     parsed = JSON.parse(raw);
>   } catch (err) {
>     const message = err instanceof Error ? err.message : String(err);
>     return { ok: false, issues: [{ code: "custom", message, path: [] }] };
>   }
> 
>   const result = configSchema.safeParse(parsed);
>   if (result.success) {
>     return { ok: true, data: result.data };
>   }
>   return { ok: false, issues: result.error.issues };
> }
> 
> // node_modules/zod/src/v4/core/tests/compile.test.ts
> function snap(schema: z.ZodType, value: unknown) {
>   const r = schema.safeParse(value);
>   return r.success ? { ok: true, data: r.data } : { ok: false, issues: r.error.issues };
> }
> 
> // Every shape the compiler refuses, with inputs that exercise the pass, fail and fallback branches of each.
> 
> // node_modules/zod/src/v4/core/core.ts
> function newError(Definition: new () => any): any {
>   const E = _E;
>   if (E) {
>     const saved = E.stackTraceLimit;
>     if (typeof saved === "number") {
>       try {
>         E.stackTraceLimit = 0;
>       } catch {
>         _E = null;
>         return new Definition();
>       }
>       try {
>         return new Definition();
>       } finally {
>         E.stackTraceLimit = saved;
>       }
>     }
>   }
>   return new Definition();
> }
> 
> export /*@__NO_SIDE_EFFECTS__*/ function $constructor<T extends ZodTrait, D = T["_zod"]["def"]>(
>   name: string,
>   initializer: (inst: T, def: D) => void,
>   /** This trait's members, installed once on every prototype that composes it. They cannot be declared in the initializer above: that runs per instance, and the prototype is shared. */
>   proto?: ProtoOf<T>,
>   params?: $constructorParams
> ): $constructor<T, D> {
>   // Prototype for this constructor's `_zod` internals. Lazily-derived fields (`values`, `pattern`, `optin`, …) install here once rather than as an accessor on every instance.
>   const zodProto: any = {};
> 
>   // Assigning the fields in the constructor body is what gives instances in-object slots; building the object literally and reparenting it costs a second allocation and a generic property copy.
>   function Internals(this: any, def: D) {
>     this.def = def;
>     this.constr = _;
>     this.traits = new Set();
>   }
>   Internals.prototype = zodProto;
> 
>   const protoMembers = proto;
>   // One trait's members land on every prototype whose chain composes it, so the answer is per prototype rather than per trait.
>   const initialized = protoMembers && new WeakSet<object>();
> 
>   function init(inst: T, def: D) {
>     if (!inst._zod) {
>       _zodDesc.value = new (Internals as any)(def);
>       try {
>         Object.defineProperty(inst, "_zod", _zodDesc);
>       } finally {
>         // Cleared even on throw, so the shared descriptor never leaks one instance's internals into the next.
>         _zodDesc.value = undefined;
>       }
>     }
> 
>     if (inst._zod.traits.has(name)) {
>       return;
>     }
> 
>     inst._zod.traits.add(name);
> 
>     initializer(inst, def);
> 
>     if (initialized) {
>       // `super(def)` from a user subclass gives `this` a prototype the subclass owns, and installing there would overwrite whatever the subclass declared. `constr` built the instance, so its prototype is the one below the subclass's that should carry the members. A receiver whose chain never reaches that prototype installs on its own, which for a plain object handed straight to `init` means `Object.prototype` — unchanged from before.
>       const own = Object.getPrototypeOf(inst);
>       const ctorProto = inst._zod.constr.prototype;
>       let up: object | null = own;
>       while (up && up !== ctorProto) up = Object.getPrototypeOf(up);
>       const target = up ?? own;
>       if (!initialized.has(target)) {
>         initialized.add(target);
>         installMembers(target, protoMembers!);
>       }
>     }
> 
>     // support prototype modifications; for-in avoids the array allocation of Object.keys on the (usually empty) prototype
>     const proto = _.prototype;
>     for (const k in proto) {
>       if (!Object.prototype.hasOwnProperty.call(proto, k)) continue;
>       if (!(k in inst)) {
>         (inst as any)[k] = proto[k].bind(inst);
>       }
>     }
>   }
> 
>   // doesn't work if Parent has a constructor with arguments
>   const Parent = params?.Parent ?? Object;
>   class Definition extends Parent {}
>   Object.defineProperty(Definition, "name", { value: name });
> 
>   function _(this: any, def: D) {
>     const inst = params?.Parent ? newError(Definition) : this;
>     init(inst, def);
>     const deferred = inst._zod.deferred;
>     if (deferred) {
>       for (const fn of deferred) {
>         fn();
>       }
>       // Released: initializers run once, and the list would otherwise be retained for the schema's lifetime.
>       inst._zod.deferred = undefined;
>     }
> 
>     // Global post-processor hook. Internal: installed by `import "zod/compile"` to enable AOT compilation for every constructed schema. Runs last, once the instance is fully built, because it hands the instance to compile(). The post-processor is expected to be reentrancy-guarded by its own implementation.
>     const pp = (globalThis as GlobalThisWithConfig).__zod_globalConfig?.postProcessor;
>     if (pp) pp(inst);
>     return inst;
>   }
> 
>   Object.defineProperty(_, "init", { value: init });
>   Object.defineProperty(_, Symbol.hasInstance, {
>     value: (inst: any) => {
>       if (params?.Parent && inst instanceof params.Parent) return true;
>       return inst?._zod?.traits?.has(name);
>     },
>   });
>   Object.defineProperty(_, "name", { value: name });
>   return _ as any;
> }
> 
> //////////////////////////////   UTILITIES   ///////////////////////////////////////
> 
> // node_modules/zod/src/v4/core/tests/compile-differential.test.ts
> function generate(rnd: () => number, depth: number): Generated {
>   const pick = <T>(xs: T[]): T => xs[Math.floor(rnd() * xs.length)];
>   const leaves = ["string", "number", "boolean", "literal", "enum", "bounded", "int"];
>   // Only object, array, optional and nullable consume `buildsValue`; every other generator calls the 4-arg `compileChild`, which defaults `needsValue` to true and puts the subtree back in full-value mode. Assert-mode-specific state only arises in chains of those four, so they are weighted to make such chains common rather than incidental.
>   const nodes = [
>     "object",
>     "looseObject",
>     "strictObject",
>     "array",
>     "optional",
>     "nullable",
>     "object",
>     "array",
>     "optional",
>     "nullable",
>     "union",
>     "tuple",
>     "record",
>     "default",
>     "catch",
>     "refine",
>     "refine",
>     "refine",
>     "transform",
>     "pipe",
>   ];
>   switch (depth <= 0 ? pick(leaves) : pick(rnd() < 0.45 ? leaves : nodes)) {
>     case "string":
>       return { schema: z.string(), ok: () => pick(["a", "", "hello"]) };
>     case "bounded":
>       return { schema: z.string().min(2).max(6), ok: () => pick(["ab", "abcdef"]) };
>     case "number":
>       return { schema: z.number(), ok: () => pick([0, 1, -1, 3.5]) };
>     case "int":
>       return { schema: z.number().int().min(0), ok: () => pick([0, 42]) };
>     case "boolean":
>       return { schema: z.boolean(), ok: () => rnd() < 0.5 };
>     case "literal":
>       return { schema: z.literal("lit"), ok: () => "lit" };
>     case "enum":
>       return { schema: z.enum(["a", "b"]), ok: () => pick(["a", "b"]) };
>     case "object":
>     case "looseObject":
>     case "strictObject": {
>       const kids: Record<string, Generated> = {};
>       const shape: Record<string, z.ZodType> = {};
>       for (let i = 0; i < 1 + Math.floor(rnd() * 3); i++) {
>         kids[`k${i}`] = generate(rnd, depth - 1);
>         shape[`k${i}`] = kids[`k${i}`].schema;
>       }
>       const ctor = pick([z.object, z.looseObject, z.strictObject]) as typeof z.object;
>       return {
>         schema: ctor(shape as never),
>         ok: () => Object.fromEntries(Object.entries(kids).map(([k, v]) => [k, v.ok()])),
>       };
>     }
>     case "array": {
>       const c = generate(rnd, depth - 1);
>       return { schema: z.array(c.schema), ok: () => Array.from({ length: Math.floor(rnd() * 3) }, () => c.ok()) };
>     }
>     case "tuple": {
>       const a = generate(rnd, depth - 1);
>       const b = generate(rnd, depth - 1);
>       return { schema: z.tuple([a.schema, b.schema]), ok: () => [a.ok(), b.ok()] };
>     }
>     case "record": {
>       const c = generate(rnd, depth - 1);
>       return { schema: z.record(z.string(), c.schema), ok: () => ({ p: c.ok(), q: c.ok() }) };
>     }
>     case "optional": {
>       const c = generate(rnd, depth - 1);
>       return { schema: z.optional(c.schema), ok: () => (rnd() < 0.3 ? undefined : c.ok()) };
>     }
>     case "nullable": {
>       const c = generate(rnd, depth - 1);
>       return { schema: z.nullable(c.schema), ok: () => (rnd() < 0.3 ? null : c.ok()) };
>     }
>     case "union": {
>       const a = generate(rnd, depth - 1);
>       const b = generate(rnd, depth - 1);
>       return { schema: z.union([a.schema, b.schema]), ok: () => (rnd() < 0.5 ? a.ok() : b.ok()) };
>     }
>     case "default": {
>       const c = generate(rnd, depth - 1);
>       return { schema: z.optional(c.schema).default(c.ok() as never), ok: () => (rnd() < 0.3 ? undefined : c.ok()) };
>     }
>     case "catch": {
>       const c = generate(rnd, depth - 1);
>       return { schema: c.schema.catch(c.ok() as never), ok: () => (rnd() < 0.4 ? 12345 : c.ok()) };
>     }
>     case "refine": {
>       const c = generate(rnd, depth - 1);
>       // Keyed to the value's own content, not a sentinel nothing produces. `refine` is the only generator that hangs a check on a container, so this predicate is what exercises the "carries checks of its own" half of `buildsValue`, and a check that can never reject leaves that half uncovered. Rejecting every empty value makes that rejection common rather than lucky.
>       return { schema: c.schema.refine(nonEmpty), ok: () => c.ok() };
>     }
>     case "transform": {
>       const c = generate(rnd, depth - 1);
>       return { schema: c.schema.transform((v: unknown) => ({ wrapped: v })), ok: () => c.ok() };
>     }
>     default: {
>       const c = generate(rnd, depth - 1);
>       return { schema: c.schema.pipe(z.any()), ok: () => c.ok() };
>     }
>   }
> }
> 
> // config.ts
> export const configSchema = z.strictObject({
>   name: z.string(),
>   port: z.number().int().min(1).max(65535),
>   adminEmail: z.email(),
> });

